mapper.select:
select a.user_id, a.account, a.user_name, a.email, null as avatar, a.phone, a.phone_cipher, a.phone_secret_key, a.sex, a.age, a.address, a.employee_no, a.id_card, a.id_card_cipher, a.id_card_secret_key, a.education, a.status, a.is_del, a.create_by, a.create_time from sys_user a where a.is_del = 0
AND a.user_id = #{userId}
AND (a.account like concat('%', #{userName}, '%') OR a.user_name like concat('%', #{userName}, '%'))
AND a.account like concat('%', #{account}, '%')
AND a.employee_no like concat('%', #{employeeNo}, '%')
AND a.education like concat('%', #{education}, '%')
AND a.id_card = #{idCard}
AND a.status = #{status}
AND a.phone like concat('%', #{phonenumber}, '%')

select distinct a.user_id, a.account, a.user_name, a.email, a.phone, a.status, a.create_time from sys_user a left join sys_user_role ur on a.user_id = ur.user_id left join sys_role r on r.role_id = ur.role_id where a.is_del = 0 and r.role_id = #{roleId}
AND (a.account like concat('%', #{userName}, '%') OR a.user_name like concat('%', #{userName}, '%'))
AND a.phone like concat('%', #{phonenumber}, '%')

mapper.update:
update sys_user
account = #{account}, user_name = #{nickName}, email = #{email}, phone = #{phonenumber}, phone_cipher = #{phoneCipher}, phone_secret_key = #{phoneSecretKey}, sex = #{sex}, age = #{age}, address = #{address}, employee_no = #{employeeNo}, id_card = #{idCard}, id_card_cipher = #{idCardCipher}, id_card_secret_key = #{idCardSecretKey}, education = #{education}, password_hash = #{password}, status = #{status}, update_by = #{updateBy}, update_time = sysdate()
where user_id = #{userId}

update sys_user
phone_cipher = #{phoneCipher}, phone_secret_key = #{phoneSecretKey}, id_card_cipher = #{idCardCipher}, id_card_secret_key = #{idCardSecretKey}, update_time = sysdate()
where user_id = #{userId}

update sys_user
avatar = FROM_BASE64(#{avatar}), full_avatar = FROM_BASE64(#{fullAvatar}), update_time = sysdate()
where user_id = #{userId}
